import click

LOGGER = logging.getLogger(__name__)
LOGGER.setLevel(logging.DEBUG)


def echo(text: str = "", color=None):
    """
    Prints a text to the console
    :param text: the text
    :param color: an optional color
    """
    if text is not click.termui and text is not str:
        text = str(text)
    if color:
        text = click.style(text, fg=color)
    if len(text) > 0:
        LOGGER.debug(text)
    click.echo(text)


def reraise_with_stack(func):
    """
    Decorator used to reraise exceptions occurring within a future.

    :param func: function to decorate
    :return: decorated function
    """

    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            traceback_str = traceback.format_exc()
            raise ValueError("Error occurred. Original traceback is\n%s\n" % traceback_str)

    return wrapped

import PIL.ExifTags
from PIL import Image


def get_exif_data(image_file_path: str) -> {}:
    """
    Tries to extract all exif data from the given image file
    :param image_file_path: path of the image file
    :return: dictionary containing all available exif data entries and their values
    """

    result = {}
    try:
        img = Image.open(image_file_path)

        exif_data = img._getexif()
        if not exif_data:
            return result

        for k, v in exif_data.items():
            if k in PIL.ExifTags.TAGS:
                tag_name = PIL.ExifTags.TAGS[k]
                result[tag_name] = v
    except Exception as e:
        pass
    return result


def get_pixel_count(image_file_path: str) -> int:
    try:
        img = Image.open(image_file_path)
        width, height = img.size
        return width * height
    except Exception as e:
        pass
    return 0

